import 'dart:convert';
import 'dart:typed_data';

/// A tiny 2.2 s H.264 MP4 (160x120, no audio) committed as base64 so the
/// local stack has a playable video without shipping a binary asset or
/// ffmpeg in the server image.
const String sampleMp4Base64 =
    '';

Uint8List sampleMp4() => base64Decode(sampleMp4Base64);

/// A valid two-page PDF with a line of text per page. Used by the seed and
/// reader tests; the app renders it with the bundled PDF viewer.
Uint8List samplePdf() {
  final page1 = 'BT /F1 24 Tf 72 720 Td (EduBox - Trang 1) Tj ET';
  final page2 = 'BT /F1 24 Tf 72 720 Td (EduBox - Trang 2) Tj ET';
  final objects = <String>[
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R 4 0 R] /Count 2 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] '
        '/Resources << /Font << /F1 5 0 R >> >> /Contents 6 0 R >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] '
        '/Resources << /Font << /F1 5 0 R >> >> /Contents 7 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    '<< /Length ${page1.length} >>\nstream\n$page1\nendstream',
    '<< /Length ${page2.length} >>\nstream\n$page2\nendstream',
  ];
  final buffer = StringBuffer('%PDF-1.4\n');
  final offsets = <int>[];
  for (final (index, object) in objects.indexed) {
    offsets.add(buffer.length);
    buffer.write('${index + 1} 0 obj\n$object\nendobj\n');
  }
  final xrefOffset = buffer.length;
  buffer.write('xref\n0 ${objects.length + 1}\n');
  buffer.write('0000000000 65535 f \n');
  for (final offset in offsets) {
    buffer.write('${offset.toString().padLeft(10, '0')} 00000 n \n');
  }
  buffer.write(
    'trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\n'
    'startxref\n$xrefOffset\n%%EOF\n',
  );
  return Uint8List.fromList(latin1.encode(buffer.toString()));
}
